// src/pages/Dashboard.js - Protected Dashboard Page
import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { getUserProfile } from '../api/authAPI';
import { getTasks, createTask, updateTask, deleteTask } from '../api/taskAPI';
import { useAuth } from '../context/AuthContext';
import TaskForm from '../components/TaskForm';
import TaskList from '../components/TaskList';

const Dashboard = () => {
  const navigate          = useNavigate();
  const { user, logout }  = useAuth();

  const [profile,  setProfile]  = useState(null);
  const [loading,  setLoading]  = useState(true);
  const [error,    setError]    = useState('');

  // Task State
  const [tasks, setTasks] = useState([]);
  const [isTaskFormVisible, setIsTaskFormVisible] = useState(false);
  const [editingTask, setEditingTask] = useState(null);

  // ---- Fetch profile & tasks from backend on mount ----
  useEffect(() => {
    const fetchData = async () => {
      try {
        const [profileData, tasksData] = await Promise.all([
          getUserProfile(),
          getTasks()
        ]);
        setProfile(profileData.user);
        setTasks(tasksData.tasks);
      } catch (err) {
        const msg = err.response?.data?.message || 'Session expired. Please log in again.';
        setError(msg);
        if (err.response?.status === 401) {
          setTimeout(() => { logout(); navigate('/login'); }, 2000);
        }
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, [logout, navigate]);

  // ---- Task Handlers ----
  const handleCreateTask = async (taskData) => {
    try {
      const data = await createTask(taskData);
      setTasks([data.task, ...tasks]);
      setIsTaskFormVisible(false);
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to create task');
    }
  };

  const handleUpdateTask = async (id, updatedFields) => {
    try {
      const data = await updateTask(id, updatedFields);
      setTasks(tasks.map((t) => (t._id === id ? data.task : t)));
      if (editingTask && editingTask._id === id) {
        setEditingTask(null);
        setIsTaskFormVisible(false);
      }
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to update task');
    }
  };

  const handleDeleteTask = async (id) => {
    if (window.confirm('Are you sure you want to delete this task?')) {
      try {
        await deleteTask(id);
        setTasks(tasks.filter((t) => t._id !== id));
      } catch (err) {
        setError(err.response?.data?.message || 'Failed to delete task');
      }
    }
  };

  const handleEditTaskClick = (task) => {
    setEditingTask(task);
    setIsTaskFormVisible(true);
    // Scroll to top where form usually is
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleCancelEdit = () => {
    setEditingTask(null);
    setIsTaskFormVisible(false);
  };

  // ---- Metrics Calculations ----
  const totalTasks = tasks.length;
  const completedTasks = tasks.filter(t => t.status === 'Completed').length;
  const pendingTasks = totalTasks - completedTasks;
  const productivityPercentage = totalTasks === 0 ? 0 : Math.round((completedTasks / totalTasks) * 100);

  // ---- Logout Handler ----
  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  // ---- Get initials for avatar ----
  const getInitials = (name) => {
    if (!name) return '?';
    return name.split(' ').map((n) => n[0]).join('').toUpperCase().slice(0, 2);
  };

  // ---- Loading state ----
  if (loading) {
    return (
      <div className="loading-container">
        <div className="spinner"></div>
        <p>Loading your workspace...</p>
      </div>
    );
  }

  const displayUser = profile || user;
  const today = new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

  return (
    <div className="dashboard-page">
      {/* ===================== NAVBAR ===================== */}
      <nav className="dashboard-nav">
        <div className="nav-brand">
          <div className="brand-dot">⚡</div>
          <span>ProductivityDash</span>
        </div>
        <div className="nav-user">
          <div className="user-avatar" title={displayUser?.name}>
            {getInitials(displayUser?.name)}
          </div>
          <button id="logout-btn" className="btn-logout" onClick={handleLogout}>
            <i className="bi bi-box-arrow-right"></i> Logout
          </button>
        </div>
      </nav>

      {/* ===================== MAIN CONTENT ===================== */}
      <main className="dashboard-main">
        {error && (
          <div className="alert-custom alert-error mb-4">
            <i className="bi bi-exclamation-circle-fill"></i> {error}
            <button className="btn-close ms-auto" onClick={() => setError('')}></button>
          </div>
        )}

        {/* Welcome Section */}
        <div className="welcome-section mb-4 d-flex justify-content-between align-items-end flex-wrap gap-3">
          <div>
            <p className="text-muted mb-1"><i className="bi bi-calendar2-week me-2"></i>{today}</p>
            <h2 className="display-6 fw-bold mb-0">Welcome back, {displayUser?.name?.split(' ')[0] || 'User'}!</h2>
          </div>
          <div>
             {!isTaskFormVisible && (
               <button className="btn-auth" onClick={() => setIsTaskFormVisible(true)}>
                 <i className="bi bi-plus-lg me-2"></i> New Task
               </button>
             )}
          </div>
        </div>

        {/* ---- Productivity Metrics Grid ---- */}
        <div className="info-grid mb-5">
          <div className="info-card stat-card">
            <div className="stat-icon bg-primary bg-opacity-10 text-primary">
              <i className="bi bi-list-task"></i>
            </div>
            <div className="stat-content">
              <h3 className="stat-value">{totalTasks}</h3>
              <p className="stat-label">Total Tasks</p>
            </div>
          </div>

          <div className="info-card stat-card">
            <div className="stat-icon bg-success bg-opacity-10 text-success">
              <i className="bi bi-check-circle"></i>
            </div>
            <div className="stat-content">
              <h3 className="stat-value">{completedTasks}</h3>
              <p className="stat-label">Completed</p>
            </div>
          </div>

          <div className="info-card stat-card">
            <div className="stat-icon bg-warning bg-opacity-10 text-warning">
              <i className="bi bi-hourglass-split"></i>
            </div>
            <div className="stat-content">
              <h3 className="stat-value">{pendingTasks}</h3>
              <p className="stat-label">Pending</p>
            </div>
          </div>

          <div className="info-card stat-card progress-card">
             <div className="d-flex justify-content-between mb-2">
               <span className="stat-label mb-0">Productivity</span>
               <span className="fw-bold text-primary">{productivityPercentage}%</span>
             </div>
             <div className="progress mt-2" style={{ height: '8px', backgroundColor: 'rgba(255,255,255,0.1)' }}>
               <div 
                 className="progress-bar bg-primary progress-bar-striped progress-bar-animated" 
                 role="progressbar" 
                 style={{ width: `${productivityPercentage}%` }} 
                 aria-valuenow={productivityPercentage} 
                 aria-valuemin="0" 
                 aria-valuemax="100"
               ></div>
             </div>
          </div>
        </div>

        {/* ---- Task Management Section ---- */}
        <div className="task-management-area">
          {isTaskFormVisible && (
            <div className="task-form-wrapper mb-5">
              <TaskForm 
                onSubmit={editingTask ? (data) => handleUpdateTask(editingTask._id, data) : handleCreateTask} 
                initialData={editingTask}
                onCancel={handleCancelEdit}
              />
            </div>
          )}

          <TaskList 
            tasks={tasks} 
            onUpdate={handleUpdateTask} 
            onDelete={handleDeleteTask}
            onEdit={handleEditTaskClick}
          />
        </div>

      </main>
    </div>
  );
};

export default Dashboard;
